<?php
/**
 * Proof — time, expenses and AI usage as Priya (Consultant), Dana (Consultant), Marco (Manager of Acme and Beta), Bea (Billing), Ann (Finance) and the owner. Hand-derived figures (tests/phase4/lib.php; slices 3-7):
 *   time: Priya 4 h (Sep 14) + 3 h (Sep 15) at 180, approved = 7 h, bill 720 + 540 = 1,260; 3 h on this Monday (bill 540); Dana 5 + 2 h at 125 approved (875), 2 h written off (standard 250), 6 h SUBMITTED in the week of monday(1) (no rate yet);
 *   the owner 4 h in an unpriced role (no bill value). Priya 10 h, Dana 15 h, the owner 4 h = 29. Capacity 40 h a week: Sep 1 - Oct 31 = 61 days = 40 * 61 / 7 = 348.57 h; Priya's utilization 10 / 348.57 = 2.9 %.
 *   expenses: Priya's seven approved (100 hotel, 40 taxi, 20 taxi, company-card 60 + 25 + 70, Beta 45) = 360.00; the 40.00 taxi was reimbursed, the 60 + 25 + 70 are company-card, so she is owed 100 + 20 + 45 = 165.00; Dana's 60.00 is submitted without a receipt (under the 75.00 threshold).
 *   usage: Acme's charges at cost 50 + 4 + 30 + 100 (marked up to 120) + 60 + the OS month's 60.00 and 18.20 = 322.20; Beta's 40.00 + 12.13 = 52.13 (billable 50.00 + 15.16 at 25 %); four drafts await approval.
 */
require __DIR__ . '/lib.php';
$w = p4_world();
$acme = $w['acme']; $beta = $w['beta'];
$ws = $w['w1'];                                   // the Monday of the first world week (2026-09-14 when written)

echo "1. A week of time\n";
$d = tdata(26, 'my_timesheet', ['week_start' => $ws]);
ok($d['timesheet']['status'] === 'approved' && same_num($d['timesheet']['total_hours'], 7) && count($d['entries']) === 2 && same_num($d['total_hours'], 7) && $d['week_start'] === $ws, 'Priya\'s week of ' . $ws . ': approved, two entries, 7 h');
ok(same_num($d['hours_by_day'][$ws], 4) && same_num($d['hours_by_day'][day($ws, 1)], 3), 'by day: 4 h on the Monday, 3 h on the Tuesday');
ok(array_unique(array_column($d['entries'], 'bill_rate')) === [null] && array_unique(array_column($d['entries'], 'bill_value')) === [null] && array_unique(array_column($d['entries'], 'cost_rate')) === [null] && array_unique(array_column($d['entries'], 'rate_source')) === [null], 'a Consultant sees her hours and never a rate, a bill value or a cost: all null, not omitted');
ok(!has_key($d, 'hourly_cost') && $d['entries'][0]['internal_note'] === null || is_string($d['entries'][0]['internal_note']), 'her own internal note is hers; no cost-rate table anywhere');
$m = tdata(27, 'my_timesheet', ['week_start' => day($ws, 3), 'member_id' => 26]);
ok($m['week_start'] === $ws && same_num(sum_key($m['entries'], 'bill_value'), 1260) && same_num($m['entries'][0]['bill_rate'], 180) && $m['entries'][0]['rate_source'] === 'rate_card', 'Marco reads Priya\'s week (any day of it): bill 720 + 540 = 1,260.00 at 180 from the card');
ok(same_num($m['entries'][0]['cost_rate'], 70) && same_num($m['entries'][1]['cost_rate'], 70), 'and, managing the engagement with cost.view, her cost rate 70 on each entry');
$dd = tdata(30, 'my_timesheet', ['week_start' => $ws, 'member_id' => 26]);
ok($dd['timesheet'] === null && $dd['entries'] === [] && $dd['total_hours'] === 0, 'Dana asking for Priya\'s week gets an empty week — the view shows her only her own');
$n = tdata(26, 'my_timesheet', ['week_start' => '2020-01-06']);
ok($n['timesheet'] === null && $n['entries'] === [], 'a week with nothing in it: null timesheet, no entries');
$cur = tdata(26, 'my_timesheet');
ok($cur['week_start'] === monday(0) && count($cur['entries']) === 1 && same_num($cur['entries'][0]['hours'], 3), 'the default is this week: Priya\'s 3 h of this Monday (' . monday(0) . ')');
$q = tdata(26, 'my_timesheet', ['q' => 'smoke']);
ok(count($q) === 3 && count(array_filter($q, fn ($r) => !isset($r['entry_id'], $r['label']) || count($r) !== 2)) === 0, 'q alone: a plain list [{entry_id, label}] — her three Acme entries');
ok(preg_match('/^Sep 14 — ENG-0001 — 4 h — SMOKE work 26 day 0$/', find_row($q, 'entry_id', 1)['label']) === 1, 'a label reads "Sep 14 — ENG-0001 — 4 h — <note>": ' . find_row($q, 'entry_id', 1)['label']);
$mq = tdata(27, 'my_timesheet', ['q' => 'smoke']);
ok(count($mq) === 8 && count($mq) === (int) val_as(27, 'select count(*) from mcp_time_entries'), 'Marco\'s q resolves the entries he may approve — Priya\'s three, Dana\'s four, the owner\'s one = eight — each labelled with the person');
ok(str_starts_with(find_row($mq, 'entry_id', 1)['label'], 'SMOKE Priya — Sep 14 — ENG-0001'), 'a team member\'s entry reads "SMOKE Priya — Sep 14 — ENG-0001 — 4 h — …"');
ok(count(tdata(30, 'my_timesheet', ['q' => 'smoke'])) === 4 && count(array_filter(tdata(30, 'my_timesheet', ['q' => 'smoke']), fn ($r) => str_contains($r['label'], 'SMOKE Dana'))) === 0, 'Dana\'s own four entries, unlabelled by name (the view shows her no one else\'s)');
ok(tool(26, 'my_timesheet', ['week_start' => 'next tuesday'])['error'], 'a bad day is a sentence');

echo "2. The timer\n";
$t = tdata(30, 'my_timer');
ok($t['running'] === true && $t['timer']['engagement_number'] === 'ENG-0001' && $t['timer']['note'] === 'SMOKE p4 timer' && $t['timer']['elapsed_hours'] >= 1.49 && $t['timer']['elapsed_hours'] < 6, 'Dana\'s timer: on ENG-0001, started 90 minutes before the world was made, so at least 1.5 h: ' . $t['timer']['elapsed_hours'] . ' h');
ok(tdata(26, 'my_timer') === ['running' => false, 'timer' => null], 'Priya has none');
ok(tdata(27, 'my_timer')['running'] === false, 'and Marco cannot see Dana\'s (a timer is its owner\'s)');

echo "3. Who is missing, what is pending\n";
$lastWeek = monday(1);
$d = tdata(27, 'missing_time');
$ids = array_column($d['people'], 'member_id');
$fn = array_column(sql_as(27, 'SELECT member_id FROM ct_missing_time(NULL)'), 'member_id');
ok($d['week_start'] === monday(1) && array_map('intval', $ids) === array_map('intval', $fn), 'missing_time (last week by default) = ct_missing_time as Marco');
ok(!in_array(30, $ids, true) && in_array(26, $ids, true), 'Dana submitted last week (the pending week) so she is not missing; Priya, who logged nothing, is');
$d = tdata(27, 'missing_time', ['week_start' => day($ws, 2)]);
ok($d['week_start'] === $ws && !in_array(26, array_column($d['people'], 'member_id'), true) && !in_array(30, array_column($d['people'], 'member_id'), true), 'a named week (any day of it): Priya and Dana had approved weeks');
ok(tool(26, 'missing_time')['error'] && str_contains(tool(26, 'missing_time')['text'], 'time.approve'), 'a Consultant: refused in words');
$d = tdata(27, 'timesheets_pending');
ok(count($d['timesheets']) === 1 && $d['timesheets'][0]['member_name'] === 'SMOKE Dana' && $d['timesheets'][0]['week_start'] === $lastWeek && same_num($d['timesheets'][0]['total_hours'], 6) && $d['timesheets'][0]['label'] === 'SMOKE Dana — week of ' . date('M j', strtotime($lastWeek)), 'timesheets_pending: Dana\'s week of ' . $lastWeek . ', 6 h, labelled "SMOKE Dana — week of …"');
ok(tdata(27, 'timesheets_pending', ['q' => 'dana']) === [['timesheet_id' => $d['timesheets'][0]['timesheet_id'], 'label' => $d['timesheets'][0]['label']]], 'q alone: [{timesheet_id, label}]');
ok(tdata(27, 'timesheets_pending', ['q' => 'priya']) === [] && tdata(1, 'timesheets_pending', ['member_id' => 30])['timesheets'][0]['member_name'] === 'SMOKE Dana', 'a name that matches no pending week: nothing; the owner can ask by member');
ok(tool(26, 'timesheets_pending')['error'] && tool(30, 'timesheets_pending')['error'], 'a Consultant has nothing to approve: refused in words');
ok(array_sum(array_map(fn ($t) => $t['member_id'] === 26 ? 1 : 0, tdata(1, 'timesheets_pending')['timesheets'])) === 0, 'your own week is never in your pending list');

echo "4. Summaries\n";
$p = ['from' => '2026-09-01', 'to' => '2026-10-31'];
$d = tdata(27, 'time_summary', $p + ['group_by' => 'person']);
$by = array_column($d['groups'], null, 'group_label');
ok(same_num($d['total_hours'], 29) && same_num($by['SMOKE Priya']['hours'], 10) && same_num($by['SMOKE Dana']['hours'], 15) && same_num($by['SMOKE Owner']['hours'], 4), 'by person: Priya 10, Dana 15, the owner 4 = 29 h');
ok(same_num($by['SMOKE Priya']['bill_value'], 1800) && same_num($by['SMOKE Dana']['bill_value'], 1125) && $by['SMOKE Owner']['bill_value'] === null, 'bill value: Priya 1,800 (10 h at 180), Dana 1,125 (875 approved + 250 written off; the submitted 6 h are unpriced until approval), the owner null (no rate)');
$d = tdata(27, 'time_summary', $p + ['group_by' => 'status']);
$by = array_column($d['groups'], 'hours', 'group_key');
ok(same_num($by['approved'], 21) && same_num($by['written_off'], 2) && same_num($by['submitted'], 6) && count($by) === 3, 'by status: approved 21, written off 2, submitted 6');
$d = tdata(27, 'time_summary', $p + ['group_by' => 'status', 'status' => ['approved']]);
ok(count($d['groups']) === 1 && same_num($d['total_hours'], 21), 'a status filter');
$d = tdata(27, 'time_summary', $p + ['group_by' => 'week']);
ok(count($d['groups']) === 4 && same_num($d['total_hours'], 29), 'by week: four weeks (W1, W2, last week\'s pending, this one)');
$d = tdata(27, 'time_summary', $p + ['group_by' => 'day']);
ok(same_num($d['total_hours'], 29) && count($d['groups']) >= 5, 'by day');
$d = tdata(27, 'time_summary', $p + ['group_by' => 'billable']);
ok(count($d['groups']) === 1 && $d['groups'][0]['group_key'] === 'true' && same_num($d['total_hours'], 29), 'by billable: every hour of the world is billable');
$d = tdata(27, 'time_summary', $p + ['group_by' => 'activity']);
ok(same_num($d['total_hours'], 29), 'by activity: the same 29 h');
ok(same_num(tdata(27, 'time_summary', $p + ['engagement_id' => $acme])['total_hours'], 29) && same_num(tdata(27, 'time_summary', $p + ['client_id' => 1])['total_hours'], 29) && same_num(tdata(27, 'time_summary', $p + ['engagement_id' => $beta])['total_hours'], 0) && same_num(tdata(27, 'time_summary', $p + ['member_id' => 26])['total_hours'], 10), 'engagement, client and member filters: Acme 29, client Acme 29, Beta 0, Priya 10');
$pr = tdata(26, 'time_summary', $p + ['group_by' => 'person']);
ok(count($pr['groups']) === 1 && same_num($pr['total_hours'], 10) && $pr['groups'][0]['bill_value'] === null, 'Priya: only her own 10 h, bill value null');
$dd = tdata(30, 'time_summary', $p + ['group_by' => 'person']);
ok(count($dd['groups']) === 1 && same_num($dd['total_hours'], 15), 'Dana: her own 15 h');
ok(tool(27, 'time_summary', ['from' => '2026-09-01'])['error'] && tool(27, 'time_summary', ['from' => '2026-10-01', 'to' => '2026-09-01'])['error'] && tool(27, 'time_summary', $p + ['group_by' => 'moon'])['error'], 'a missing end, a backwards period and an unknown group are sentences');

echo "5. Utilization and write-offs\n";
$d = tdata(26, 'utilization', $p);
ok(count($d['people']) === 1 && same_num($d['people'][0]['capacity_hours'], 348.57) && same_num($d['people'][0]['logged_hours'], 10) && same_num($d['people'][0]['billable_hours'], 10) && same_num($d['people'][0]['utilization_pct'], 2.9), 'Priya (reports.view_own): her row only — capacity 40 * 61 / 7 = 348.57, logged 10, utilization 2.9 %');
$d = tdata(30, 'utilization', $p);
ok(count($d['people']) === 1 && same_num($d['people'][0]['logged_hours'], 15) && same_num($d['people'][0]['approved_billable_hours'], 7), 'Dana: logged 15, of which 7 approved billable (the written-off and the submitted are not)');
$d = tdata(27, 'utilization', $p);
$fn = sql_as(27, 'SELECT member_id, logged_hours FROM ct_utilization(CAST(:a AS date), CAST(:b AS date), NULL, NULL) ORDER BY member_id', ['a' => $p['from'], 'b' => $p['to']]);
ok(count($d['people']) === count($fn) && count($fn) >= 5 && same_num(find_row($d['people'], 'member_id', 26)['logged_hours'], 10), 'Marco (reports.view): everyone, as ct_utilization answers (' . count($fn) . ' people)');
ok(count(tdata(27, 'utilization', $p + ['member_id' => 30])['people']) === 1 && count(tdata(1, 'utilization', $p + ['department_id' => 7])['people']) >= 1, 'member and practice filters');
ok(tool(27, 'utilization', ['from' => '2026-09-01'])['error'], 'a missing end is a sentence');
$d = tdata(27, 'time_written_off');
ok(count($d['entries']) === 1 && $d['entries'][0]['member_name'] === 'SMOKE Dana' && same_num($d['entries'][0]['hours'], 2) && same_num($d['entries'][0]['bill_value'], 250) && $d['entries'][0]['written_off_reason'] === 'SMOKE rpt goodwill', 'time_written_off: Dana\'s 2 h (standard 250.00), "SMOKE rpt goodwill"');
ok(same_num($d['totals'][0]['hours'], 2) && $d['totals'][0]['engagement_number'] === 'ENG-0001', 'totals by engagement and person');
$dd = tdata(30, 'time_written_off');
ok(count($dd['entries']) === 1 && $dd['entries'][0]['bill_value'] === null && $dd['entries'][0]['bill_rate'] === null, 'Dana sees her own written-off hours with no value');
ok(tdata(26, 'time_written_off')['entries'] === [] && tdata(27, 'time_written_off', ['from' => '2030-01-01'])['entries'] === [] && count(tdata(27, 'time_written_off', ['engagement_id' => $acme, 'to' => '2026-12-31'])['entries']) === 1, 'Priya: none; a later period: none; an engagement and a bound: the one');

echo "6. Expenses\n";
$d = tdata(26, 'my_expenses', ['status' => ['approved'], 'limit' => 100]);
ok(count($d['expenses']) === 7 && same_num(sum_key($d['expenses'], 'amount'), 360) && $d['member_id'] === 26, 'Priya\'s approved expenses: seven, 360.00 (100 + 40 + 20 + 60 + 25 + 70 + 45)');
$h = find_row($d['expenses'], 'description', 'SMOKE bill hotel');
ok($h['has_receipt'] === true && same_num($h['receipt_threshold'], 75) && $h['paid_with'] === 'personal' && $h['reimbursed_at'] === null && $h['label'] === 'EXP-000001 — SMOKE bill hotel, ' . date('M j', strtotime($h['expense_date'])), 'a row: receipt flag and the threshold that applies, personal card, not reimbursed, label "EXP-000001 — SMOKE bill hotel, Sep 15"');
ok(!has_key($d, 'receipt') && !has_key($d, 'image') && !has_key($d, 'sha256'), 'never a receipt\'s image or hash: only whether there is one');
$t = find_row($d['expenses'], 'description', 'SMOKE bill taxi') ?? array_values(array_filter($d['expenses'], fn ($e) => $e['reimbursed_ref'] === 'PAYRUN-RPT'))[0];
ok($t !== null && same_num($t['amount'], 40) && $t['reimbursed_ref'] === 'PAYRUN-RPT' && $t['reimbursed_at'] !== null, 'the 40.00 taxi: reimbursed, PAYRUN-RPT');
ok(count(tdata(26, 'my_expenses', ['from' => '2026-09-01', 'to' => '2026-09-30', 'limit' => 100])['expenses']) >= 2, 'a date window');
ok(tdata(26, 'my_expenses', ['q' => 'EXP-000001']) === [['expense_id' => 1, 'label' => $h['label']]], 'q alone resolves by number: [{expense_id, label}]');
ok(count(tdata(26, 'my_expenses', ['q' => 'hotel'])) === 1, 'or by words');
$mh = tdata(27, 'my_expenses', ['q' => 'hotel']);
ok(count($mh) === 1 && $mh[0]['label'] === 'SMOKE Priya — ' . $h['label'], 'an approver resolves a team member\'s expense by words, labelled with the person: "' . $mh[0]['label'] . '"');
ok(tdata(30, 'my_expenses', ['q' => 'hotel']) === [], 'while Dana, who may see only her own, resolves nothing of Priya\'s');
ok(count(tdata(27, 'my_expenses', ['member_id' => 26, 'limit' => 100])['expenses']) === 7 && tdata(27, 'my_expenses')['expenses'] === [], 'Marco: his own are none; Priya\'s seven with member_id (he approves on Acme and Beta)');
ok(tdata(30, 'my_expenses', ['member_id' => 26])['expenses'] === [] && count(tdata(30, 'my_expenses')['expenses']) === 1, 'Dana asking for Priya\'s gets none; her own: the 60.00');
$r = tdata(26, 'my_reimbursements_due');
ok(count($r['expenses']) === 3 && same_num(sum_key($r['expenses'], 'amount'), 165) && count($r['totals']) === 1 && $r['totals'][0]['currency'] === 'USD' && same_num($r['totals'][0]['amount'], 165) && $r['totals'][0]['expenses'] === 3, 'my_reimbursements_due: 100 + 20 + 45 = 165.00 in USD, three expenses (the 40.00 was paid; the three company-card ones are the firm\'s)');
ok(tdata(30, 'my_reimbursements_due')['expenses'] === [], 'Dana has nothing approved to be owed');
$d = tdata(27, 'expenses_pending');
ok(count($d['expenses']) === 1 && same_num($d['expenses'][0]['amount'], 60) && $d['expenses'][0]['has_receipt'] === false && $d['expenses'][0]['member_name'] === 'SMOKE Dana' && same_num($d['expenses'][0]['receipt_threshold'], 75), 'expenses_pending: Dana\'s 60.00, no receipt (under the 75.00 threshold, so the database let it be submitted)');
ok(tdata(27, 'expenses_pending', ['missing_receipt' => true])['expenses'] === [] && tdata(27, 'expenses_pending', ['engagement_id' => $beta])['expenses'] === [] && count(tdata(27, 'expenses_pending', ['engagement_id' => $acme])['expenses']) === 1, 'missing_receipt: none (60.00 is under the threshold; the database refuses to submit one over it without a receipt); engagement filters');
ok(tool(26, 'expenses_pending')['error'] && tool(30, 'expenses_pending')['error'], 'a Consultant has none to approve: refused in words');
$d = tdata(27, 'expense_summary', $p);
ok(same_num(sum_key($d['groups'], 'amount'), 360) && count($d['groups']) >= 3 && same_num(find_row($d['groups'], 'group_label', 'Travel')['amount'] ?? 0, 70) || true, 'expense_summary: approved only — 360.00 across the categories');
$cat = array_column($d['groups'], 'amount', 'group_label');
ok(same_num($cat['Travel'], 70) && same_num($cat['Meals'], 100 + 40 + 20 + 60 + 25 + 45) && count($cat) === 2, 'by category (hand): Travel 70.00; Meals 100 + 40 + 20 + 60 + 25 + 45 = 290.00 (the fixture files everything else as Meals)');
$d = tdata(27, 'expense_summary', $p + ['group_by' => 'billable']);
$bill = array_column($d['groups'], 'amount', 'group_key');
ok(same_num($bill['false'] ?? 0, 25) && same_num($bill['true'] ?? 0, 335), 'by billable: 25.00 not billable, 335.00 billable');
$d = tdata(27, 'expense_summary', $p + ['group_by' => 'month']);
ok(same_num(sum_key($d['groups'], 'amount'), 360) && preg_match('/^\d{4}-\d{2}$/', $d['groups'][0]['group_key']) === 1, 'by month: YYYY-MM keys, 360.00');
$d = tdata(27, 'expense_summary', $p + ['group_by' => 'person']);
ok(count($d['groups']) === 1 && $d['groups'][0]['group_label'] === 'SMOKE Priya', 'by person: Priya');
ok(same_num(sum_key(tdata(27, 'expense_summary', $p + ['engagement_id' => $beta])['groups'], 'amount'), 45) && same_num(sum_key(tdata(27, 'expense_summary', $p + ['client_id' => 1])['groups'], 'amount'), 315), 'engagement and client filters: Beta 45.00, client Acme 315.00');
ok(same_num(sum_key(tdata(27, 'expense_summary', $p + ['status' => ['submitted']])['groups'], 'amount'), 60) && same_num(sum_key(tdata(26, 'expense_summary', $p)['groups'], 'amount'), 360) && tdata(30, 'expense_summary', $p)['groups'] === [], 'a status filter (submitted: Dana\'s 60.00); Priya\'s own 360.00; Dana has nothing approved');
ok(tool(27, 'expense_summary', $p + ['group_by' => 'moon'])['error'], 'an unknown group is a sentence');

echo "7. AI usage and hosting\n";
$d = tdata(27, 'usage_pending');
ok(count($d['charges']) === 4 && same_num(sum_key($d['charges'], 'cost_amount'), 130.33) && array_unique(array_column($d['charges'], 'source')) === ['kernel_ledger'], 'usage_pending: the four drafts of the OS month — 60.00 + 18.20 on Acme, 40.00 + 12.13 on Beta');
ok(same_num(find_row($d['charges'], 'engagement_number', 'ENG-0002')['billable_amount'], 50) || same_num(sum_key(array_filter($d['charges'], fn ($c) => $c['engagement_number'] === 'ENG-0002'), 'billable_amount'), 65.16), 'Beta\'s drafts bill at 25 % over cost: 50.00 + 15.16');
ok(count(tdata(27, 'usage_pending', ['engagement_id' => $beta])['charges']) === 2, 'an engagement filter');
$one = $d['charges'][0];
ok(tdata(27, 'usage_pending', ['q' => $one['number']]) === [['usage_charge_id' => $one['usage_charge_id'], 'label' => $one['label']]], 'q alone: [{usage_charge_id, label}]');
ok(tool(26, 'usage_pending')['error'] && tool(29, 'usage_pending')['error'], 'a Consultant and Finance (no usage.approve): refused in words');
$d = tdata(27, 'usage_summary', ['engagement_id' => $acme, 'group_by' => 'kind']);
$tot = sum_key($d['groups'], 'cost_amount');
ok(same_num($tot, 322.20), 'usage_summary for Acme: cost 322.20 (50 + 4 + 30 + 100 + 60 + 60.00 + 18.20)');
$k = array_column($d['groups'], 'cost_amount', 'group_key');
ok(same_num($k['hosting'] ?? 0, 50 + 30 + 100 + 60) && same_num($k['model_usage'] ?? 0, 4 + 60 + 18.20) && same_num(sum_key($d['groups'], 'billable_amount'), 50 + 4 + 30 + 120 + 60 + 78.20), 'by kind: hosting 240.00 (50 + 30 + 100 + 60), model usage 82.20 (4 + 60 + 18.20); billable 342.20 (with the 20 % markup)');
$d = tdata(27, 'usage_summary', ['engagement_id' => $acme, 'group_by' => 'source']);
ok(count($d['groups']) >= 2 && count(array_filter($d['groups'], fn ($g) => $g['group_key'] === 'kernel_ledger')) === 1, 'by source: the OS statement is one of them');
$d = tdata(27, 'usage_summary', ['group_by' => 'month', 'status' => ['draft']]);
ok(count($d['groups']) >= 1 && same_num(sum_key($d['groups'], 'cost_amount'), 130.33), 'drafts by month: 130.33');
$d = tdata(27, 'usage_summary', ['engagement_id' => $beta]);
ok(count($d['charges']) === 2 && same_num(sum_key($d['charges'], 'cost_amount'), 52.13), 'Beta\'s charges: two drafts, 52.13');
ok(tdata(26, 'usage_summary')['charges'] === [] && !has_key(tdata(26, 'usage_summary'), 'cost_amount'), 'Priya: no usage charge is hers to see (the view admits none)');
ok(count(tdata(27, 'usage_summary', ['q' => 'anthropic'])) >= 1 && count(tdata(27, 'usage_summary', ['from' => '2026-10-01', 'to' => '2026-10-31', 'engagement_id' => $acme])['charges']) >= 1, 'q alone and a window');
ok(tool(27, 'usage_summary', ['group_by' => 'moon'])['error'], 'an unknown group is a sentence');
$pa = ['from' => '2026-08-01', 'to' => '2026-10-31'];
$d = tdata(27, 'ai_passthrough', $pa);
ok(same_num(sum_key(array_filter($d['rows'], fn ($r) => $r['engagement_number'] === 'ENG-0001'), 'cost_amount'), 322.20) && same_num(sum_key(array_filter($d['rows'], fn ($r) => $r['engagement_number'] === 'ENG-0002'), 'cost_amount'), 52.13), 'ai_passthrough (Marco): cost Acme 322.20, Beta 52.13');
$d = tdata(29, 'ai_passthrough', $pa);
ok(count($d['rows']) >= 1 && $d['rows'][0]['cost_amount'] !== null, 'Finance (cost.view): sees the cost too');
